import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import yaml

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = '/tmp/reports'
app.config['MAX_CONTENT_LENGTH'] = 5 * 1024 * 1024

ALLOWED_EXTENSIONS = {'yaml', 'yml'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def render_report(template_path, output_path, context):
    """Render a report using system pandoc with yaml metadata"""
    cmd = [
        'pandoc',
        '--metadata-file', template_path,
        '--template', '/opt/reports/base.tex',
        '-o', output_path,
        '/dev/null'
    ]
    env = os.environ.copy()
    env['REPORT_CONTEXT'] = str(context)
    result = subprocess.run(cmd, capture_output=True, text=True, env=env, timeout=30)
    return result.returncode == 0

def validate_yaml_structure(data):
    """Validate that YAML has expected report fields"""
    required = ['title', 'author', 'date']
    if not isinstance(data, dict):
        return False
    return all(k in data for k in required)

@app.route('/api/report/generate', methods=['POST'])
def generate_report():
    if 'config' not in request.files:
        return jsonify({'error': 'No config file provided'}), 400

    file = request.files['config']
    if file.filename == '':
        return jsonify({'error': 'No file selected'}), 400

    if not allowed_file(file.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    filename = secure_filename(file.filename)

    # Save uploaded YAML to temp location
    upload_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    file.save(upload_path)

    try:
        # Parse YAML - using yaml.load with FullLoader for compatibility
        with open(upload_path, 'r') as f:
            content = f.read()

        # Basic size check
        if len(content) > 65536:
            os.unlink(upload_path)
            return jsonify({'error': 'Config too large'}), 400

        data = yaml.load(content, Loader=yaml.FullLoader)

        if not validate_yaml_structure(data):
            os.unlink(upload_path)
            return jsonify({'error': 'Invalid YAML structure'}), 400

        # Generate output path
        output_filename = filename.rsplit('.', 1)[0] + '.pdf'
        output_path = os.path.join(tempfile.gettempdir(), output_filename)

        # Render report
        success = render_report(upload_path, output_path, data)

        # Cleanup input
        os.unlink(upload_path)

        if success and os.path.exists(output_path):
            return send_file(output_path, as_attachment=True, download_name=output_filename)
        else:
            return jsonify({'error': 'Report generation failed'}), 500

    except yaml.YAMLError as e:
        os.unlink(upload_path)
        return jsonify({'error': f'YAML parse error: {str(e)}'}), 400
    except Exception as e:
        if os.path.exists(upload_path):
            os.unlink(upload_path)
        return jsonify({'error': 'Internal error'}), 500

@app.route('/api/report/templates', methods=['GET'])
def list_templates():
    templates_dir = '/opt/reports/templates'
    if os.path.isdir(templates_dir):
        files = os.listdir(templates_dir)
        return jsonify({'templates': files})
    return jsonify({'templates': []})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.3.1'})

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
